WITH enriched AS (SELECT id, full_name, email, dept_id, hire_date, is_remote, LEAD(salary) OVER (PARTITION BY job_title ORDER BY salary, id) AS next_salary, LAG(salary) OVER (PARTITION BY job_title ORDER BY salary, id) AS prev_salary, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary, id) AS event_seq FROM employees) SELECT id, dept_id, hire_date, next_salary, event_seq FROM enriched;
